INSERT INTO `quest_request_items` (`ID`, `EmoteOnComplete`, `EmoteOnIncomplete`, `CompletionText`, `VerifiedBuild`) VALUES
(9105001, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105002, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105003, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105004, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105005, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105006, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105007, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105008, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105010, 1, 1, 'Six wolves, I said. I can count your meals, little horror. I can smell them on you.', 0),
(9105011, 1, 1, 'Out of time? We''ll go again! I''ll hold the spoon better.', 0),
(9105012, 1, 1, 'Hogger is still the hungriest thing in Elwynn. That should bother you more than it does.', 0),
(9105019, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105020, 1, 1, 'Your belly is still light, little horror. Six troggs.', 0),
(9105021, 1, 1, 'They will let you in, little horror. If you let them.', 0),
(9105022, 1, 1, 'The white wolf''s trail is still out there. Sniff it out, little horror.', 0),
(9105023, 1, 1, 'The Backbreakers still dig, little horror. One of them, I said.', 0),
(9105029, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105030, 1, 1, 'Six cats. They are quiet, but they are not hidden from you.', 0),
(9105031, 1, 1, 'They are waiting for one more cat, little horror.', 0),
(9105032, 1, 1, 'Well? What did it see? Go and look!', 0),
(9105033, 1, 1, 'The queen still sits in her web.', 0),
(9105034, 1, 1, 'Moss and milk and moonlight, Snack. Follow it.', 0),
(9105039, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105040, 1, 1, 'Six striders, little horror. They run, but not far.', 0),
(9105041, 1, 1, 'Still five bullies, Snack. Bigger roar!', 0),
(9105042, 1, 1, 'Three owlbeasts, and their moon. Their madness keeps them home; go to them.', 0),
(9105043, 1, 1, 'Moss and feathers and getting up again, Snack.', 0),
(9105049, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105050, 1, 1, 'Six boars. They come to you if you stand still long enough.', 0),
(9105051, 1, 1, '*gasp* I ran out of breath! Again! Say yes again!', 0),
(9105052, 1, 1, 'They are still lying in the river. Go and remind them.', 0),
(9105053, 1, 1, 'Eggshell and dust, Snack. It''s still hissing out there.', 0),
(9105054, 1, 1, 'Six quilboar, little horror, head first.', 0),
(9105059, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105060, 1, 1, 'Six striders. They will not stop running for you.', 0),
(9105061, 1, 1, 'Still drilling, Snack. Roar louder!', 0),
(9105062, 1, 1, 'Mazzranache still wanders. Follow your nose, little horror.', 0),
(9105063, 1, 1, 'Dust and grass and trying very hard, Snack.', 0),
(9105069, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105070, 1, 1, 'Six bats. Listen for them; they are listening for you.', 0),
(9105071, 1, 1, 'The candle went out! I''ll light another one. Go!', 0),
(9105072, 1, 1, 'Five crusaders, and one prayer of fire. They are easy to find; they shout.', 0),
(9105079, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105080, 1, 1, 'Six of them. The sanctums hum with them.', 0),
(9105081, 1, 1, 'Still popping, Snack!', 0),
(9105082, 1, 1, 'Six of the Wretched. They will not be missed.', 0),
(9105084, 1, 1, 'Six Wretched, Snack, and you have to be the squiggle.', 0),
(9105089, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105100, 1, 1, 'Imaginary stew needs real goretusks, Snack.', 0),
(9105101, 1, 1, 'They are waiting, little horror. Go and wait with them.', 0),
(9105103, 1, 1, 'The old one still eats the coast.', 0),
(9105105, 1, 1, 'Six Defias, Snack. Peck peck.', 0),
(9105109, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105110, 1, 1, 'Six troggs. They are still digging.', 0),
(9105111, 1, 1, 'The fire is lit. Bring her, and sit.', 0),
(9105113, 1, 1, 'It is still at the bottom of the loch. Follow your nose around the shore.', 0),
(9105114, 1, 1, 'Honey and bark, Snack. And silly decisions.', 0),
(9105119, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105120, 1, 1, 'Six moonstalkers. They are darker than the night, but not darker than you.', 0),
(9105121, 1, 1, 'They are hooting for you, little horror.', 0),
(9105122, 1, 1, 'The oracles still call the moon. Go and be called.', 0),
(9105123, 1, 1, 'The cat still hunts in silence. Follow the ash.', 0),
(9105129, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105130, 1, 1, 'Six hatchlings, Snack. They''re getting ideas.', 0),
(9105131, 1, 1, 'The fire is lit. Bring her.', 0),
(9105132, 1, 1, 'Three anomalies, and the place where they come through.', 0),
(9105133, 1, 1, 'Did you see the bones? Go and stand there, Snack.', 0),
(9105135, 1, 1, 'Five sleepy bears, Snack. Shh.', 0),
(9105136, 1, 1, 'Five anomalies, little horror, spat at properly.', 0),
(9105139, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105140, 1, 1, 'Six striders. They will not stand still for you.', 0),
(9105141, 1, 1, 'They''re still laughing, Snack. Laugh LOUDER.', 0),
(9105142, 1, 1, 'Three lizards, and Bramble has to see.', 0),
(9105143, 1, 1, 'The hatchlings still nest in the south. Follow the rain.', 0),
(9105144, 1, 1, 'I''m RIGHT HERE, Snack.', 0),
(9105145, 1, 1, 'Dust and milk and being frightened, Snack.', 0),
(9105146, 1, 1, 'Six quilboar, Snack. They''re still throwing rocks.', 0),
(9105149, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105150, 1, 1, 'Six worgs. They watch you from the pines.', 0),
(9105151, 1, 1, 'Still howling, Snack. Still awake. Shoo harder.', 0),
(9105152, 1, 1, 'They are waiting at the wall, little horror. Run behind them.', 0),
(9105153, 1, 1, 'Five Rot Hides, and one curse. The isle is full of both.', 0),
(9105155, 1, 1, 'Five Rot Hides, little horror, opened properly.', 0),
(9105159, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105160, 1, 1, 'Six cats. They are thin; you will have to be quick.', 0),
(9105162, 1, 1, 'They are still calling themselves devourers.', 0),
(9105163, 1, 1, '...two hundred and ninety-nine, three hundred. Are they gone? THEY''RE NOT GONE. Again!', 0),
(9105165, 1, 1, 'Five spells, little horror, swallowed before they land.', 0),
(9105169, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105170, 1, 1, 'Six wolves. They are easy to find; they want to find you.', 0),
(9105171, 1, 1, 'The fire is lit. Do not keep the night waiting.', 0),
(9105173, 1, 1, 'The shining wolf still walks. Follow the moonlight.', 0),
(9105179, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105180, 1, 1, 'The shallows are still crowded.', 0),
(9105181, 1, 1, 'They are waiting for one more lost one.', 0),
(9105182, 1, 1, 'Four whelps, Snack, and Bramble has to see them snort.', 0),
(9105183, 1, 1, 'No croc yet, Snack. The spoon is waiting.', 0),
(9105189, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105190, 1, 1, 'Six ghostpaws. Quiet things; be quieter.', 0),
(9105191, 1, 1, 'The fire is lit. This one matters.', 0),
(9105192, 1, 1, 'Five satyrs. They are loud; follow the noise.', 0),
(9105193, 1, 1, 'They are still knocking on the door.', 0),
(9105195, 1, 1, 'Five fanatics, little horror. Fangs first.', 0),
(9105199, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105200, 1, 1, 'Six bears. They are slow; do not make me wait longer than they do.', 0),
(9105202, 1, 1, 'The candle is out. Wren is lighting another. Five lions.', 0),
(9105203, 1, 1, 'They are sunning. Go and do nothing with them.', 0),
(9105209, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105210, 1, 1, 'Still under the blanket, Snack.', 0),
(9105211, 1, 1, 'Five pridewings. They fly, but they come down to feed.', 0),
(9105212, 1, 1, 'No verdict yet, Snack. Bramble has to see it.', 0),
(9105213, 1, 1, 'The drake is still on its peak. Climb.', 0),
(9105215, 1, 1, 'Six loggers, Snack. KICK.', 0),
(9105219, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105220, 1, 1, 'Six hyenas. They''re still nipping, Snack.', 0),
(9105221, 1, 1, 'Did you see the canyon? Go and stand in it.', 0),
(9105223, 1, 1, 'The basilisks still stare at nothing.', 0),
(9105224, 1, 1, 'Dust and hiccups, Snack.', 0),
(9105225, 1, 1, 'Five centaur, little horror, from behind.', 0),
(9105229, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105230, 1, 1, 'Six young cats. They are everywhere; so is the heat.', 0),
(9105232, 1, 1, 'Still puffing up, Snack. Flex HARDER.', 0),
(9105233, 1, 1, 'Eight, Snack. And you have to be a toad when you do it. Those are the rules. I made them up.', 0),
(9105234, 1, 1, 'The shadowmaws are still in the dark.', 0),
(9105239, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105240, 1, 1, 'Six drywallows. They lie in the driest mud.', 0),
(9105241, 1, 1, 'Three spikeshells, and their barbs. Mind your mouth.', 0),
(9105243, 1, 1, 'Six murlocs, Snack, as a toad. They''re still stealing frogspawn.', 0),
(9105245, 1, 1, 'The fire is lit. Sit.', 0),
(9105246, 1, 1, 'The worm is still under the mud. Follow the stench.', 0),
(9105248, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105249, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105250, 1, 1, 'Five lions. The big ones, mostly.', 0),
(9105251, 1, 1, 'Four of them, Snack. Kindly. And Bramble has to see.', 0),
(9105252, 1, 1, 'The fury is still in the mountain. Follow the flint.', 0),
(9105253, 1, 1, 'The drake still sits on its point. Are you strong enough yet?', 0),
(9105254, 1, 1, 'Wool and snow and being brave, Snack.', 0),
(9105255, 1, 1, 'Five ogres, little horror, with the stone jaws.', 0),
(9105259, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105260, 1, 1, 'Six blisterpaws, Snack. Their paws still hurt.', 0),
(9105261, 1, 1, 'Did you see the beach? Go and stand on it.', 0),
(9105262, 1, 1, 'Six Sandfury, in your serpent''s shape. They are still praying.', 0),
(9105264, 1, 1, 'Four rocs, Snack, and Bramble has to see.', 0),
(9105265, 1, 1, 'Hot sand and confusion, Snack.', 0),
(9105266, 1, 1, 'They are staring, little horror. Let them.', 0),
(9105269, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105270, 1, 1, 'Six longtooths. Mind their teeth.', 0),
(9105271, 1, 1, 'Five ironfurs, Snack, and Bramble has to see.', 0),
(9105272, 1, 1, 'They are preening, little horror. Go and preen with them.', 0),
(9105274, 1, 1, 'The sand ran out. Wren has turned it over. Four groddoc.', 0),
(9105279, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105280, 1, 1, 'Six silvermanes. They shine; you will find them.', 0),
(9105281, 1, 1, 'The fire is lit, and the moon is up. Sit.', 0),
(9105282, 1, 1, 'Five owlbeasts. They have forgotten the moon; do not let them forget you.', 0),
(9105284, 1, 1, 'Gammerita is still cross on her cliffs. Follow the grudges.', 0),
(9105289, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105290, 1, 1, 'Six ravasaurs. They hunt in packs; so can you.', 0),
(9105291, 1, 1, 'Five pterrordax, Snack. One''s circling me right now.', 0),
(9105293, 1, 1, 'The fire is lit. Sit.', 0),
(9105294, 1, 1, 'Eight bugs, Snack. Snap snap. As a toad!', 0),
(9105296, 1, 1, 'The devilsaur still walks. Listen for it. Smell it first.', 0),
(9105299, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105300, 1, 1, 'Six shardtooths. They are cold; you will warm them.', 0),
(9105302, 1, 1, 'They are waiting under the moon.', 0),
(9105303, 1, 1, 'Four chimaeras, Snack. Eight heads.', 0),
(9105305, 1, 1, 'The moon-touched still wander the snow. Follow the moonlight.', 0),
(9105309, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105310, 1, 1, 'Five ember worgs. Follow the smoke.', 0),
(9105311, 1, 1, 'Six of the black brood, after you have walked among them.', 0),
(9105313, 1, 1, 'Did you see the path? Go and stand there.', 0),
(9105314, 1, 1, 'Ten, little horror. In your drake''s own shape.', 0),
(9105319, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105320, 1, 1, 'Six worgs. I can hear them through the thread.', 0),
(9105322, 1, 1, 'They are blinking in the forest. Go and blink with them.', 0),
(9105323, 1, 1, 'The fire is lit. The thread is thin; do not make me wait.', 0),
(9105324, 1, 1, 'Four and three, Snack. Bones bones bones.', 0),
(9105329, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105330, 1, 1, 'Six talbuk. They graze as if nothing were wrong.', 0),
(9105331, 1, 1, 'Lost the hat! Found it. Again! Five windrocs.', 0),
(9105333, 1, 1, 'Five voidspawn, in your void''s own shape.', 0),
(9105339, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105340, 1, 1, 'Six chasers. They chase; you catch.', 0),
(9105341, 1, 1, 'Five phase hunters, and Bramble has to see.', 0),
(9105343, 1, 1, 'Four shimmerwings, Snack. And walk in nicely.', 0),
(9105344, 1, 1, 'Three nether drakes. Climb the ridge.', 0),
(9105345, 1, 1, 'Six chasers, little horror, torn properly.', 0),
(9105348, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105349, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105350, 1, 1, 'Six shoveltusk. They are digging; dig them up.', 0),
(9105351, 1, 1, 'The fire is lit. Sit.', 0),
(9105352, 1, 1, 'The clutch is warm, and waiting for one more.', 0),
(9105353, 1, 1, 'Two proto-drakes, and one breath. They guard the clutch.', 0),
(9105359, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105360, 1, 1, 'Five rhinos. They are hard to miss.', 0),
(9105361, 1, 1, 'Five moths, Snack. Achoo.', 0),
(9105363, 1, 1, 'Four of the blue''s servants. Coldarra is in the west.', 0),
(9105369, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105370, 1, 1, 'Six wolves. Follow the singing.', 0),
(9105371, 1, 1, 'Five eagles, Snack. They still think they own the sky.', 0),
(9105372, 1, 1, 'The fire is lit. The hills are breathing. Sit.', 0),
(9105374, 1, 1, 'Three bears. Go carefully near the den.', 0),
(9105379, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105381, 1, 1, 'Six crocolisks, Snack. Count the logs.', 0),
(9105382, 1, 1, 'Five dreadsabers, as a saber. They hunt the hunters; you hunt them.', 0),
(9105383, 1, 1, 'Three hundred bangs! Out of time! I''ll start again. *BANG*', 0),
(9105385, 1, 1, 'The first dragons still nest in the north-east. Follow the green fire.', 0),
(9105389, 1, 1, 'The lantern is not lit yet? Then you are not there yet, little horror.', 0),
(9105390, 1, 1, 'Five crystal spiders, Snack. Crunch.', 0),
(9105391, 1, 1, 'Four jormungar, as a borer. Listen for the ice breaking.', 0),
(9105392, 1, 1, 'Snow and fur and no war, Snack.', 0),
(9105393, 1, 1, 'Four of the storm''s children, and one blow. Climb.', 0),
(9105394, 1, 1, 'Ten, little horror. In your storm.', 0),
(9105395, 1, 1, 'The fire is lit. We are waiting. Bring her.', 0);
INSERT INTO `quest_offer_reward` (`ID`, `Emote1`, `RewardText`, `VerifiedBuild`) VALUES
(9105001, 1, 'There you are. The flame knew you before I did.$B$BSit, hungry thing. Your home is full of meals, and every meal is a lesson. Some are not meals at all; I will tell you which.', 0),
(9105002, 1, 'There you are. The flame knew you before I did.$B$BSit, hungry thing. Your home is full of meals, and every meal is a lesson. Some are not meals at all; I will tell you which.', 0),
(9105003, 1, 'There you are. The flame knew you before I did.$B$BSit, hungry thing. Your home is full of meals, and every meal is a lesson. Some are not meals at all; I will tell you which.', 0),
(9105004, 1, 'There you are. The flame knew you before I did.$B$BSit, hungry thing. Your home is full of meals, and every meal is a lesson. Some are not meals at all; I will tell you which.', 0),
(9105005, 1, 'There you are. The flame knew you before I did.$B$BSit, hungry thing. Your home is full of meals, and every meal is a lesson. Some are not meals at all; I will tell you which.', 0),
(9105006, 1, 'There you are. The flame knew you before I did.$B$BSit, hungry thing. Your home is full of meals, and every meal is a lesson. Some are not meals at all; I will tell you which.', 0),
(9105007, 1, 'There you are. The flame knew you before I did.$B$BSit, hungry thing. Your home is full of meals, and every meal is a lesson. Some are not meals at all; I will tell you which.', 0),
(9105008, 1, 'There you are. The flame knew you before I did.$B$BSit, hungry thing. Your home is full of meals, and every meal is a lesson. Some are not meals at all; I will tell you which.', 0),
(9105010, 1, 'Fear, mostly. And rabbit. That is the taste of a wolf that runs alone.$B$BTake something for your trouble. Old things I have kept; they will fit a shape like yours better than they fit me.', 0),
(9105011, 1, 'SIX! Before the spoon! You''re the champion of the lake. The champion of Elwynn. Of everywhere I''ve timed, which is here.$B$BHere''s your prize. I made a ribbon, but Hagatha made me give you this instead.', 0),
(9105012, 1, 'Now you are the hungriest thing in Elwynn. Do not let it go to your head; it is a very small forest.$B$BRemember how his charge felt, and the taste after. That is how a Devourer learns: first the blow, then the meal.', 0),
(9105019, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Westfall too.', 0),
(9105020, 1, 'Heavy, is it? Good. A thing that carries stone inside it does not fall over easily.$B$BTake one of these. Something to wear over the weight.', 0),
(9105021, 1, 'You stood among them and they did not know you. Remember how that felt: being one of many, and none of them knowing what you are.$B$BTake this.', 0),
(9105022, 1, 'The white wolf, inside you. The dwarves will tell their children Timber finally lost a hunt.$B$BTake this.', 0),
(9105023, 1, 'Now you have tasted what a trogg grows into. Remember it: one day your own stone will crack open and something like that will crawl out.$B$BWear this until then.', 0),
(9105029, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Loch Modan too.', 0),
(9105030, 1, 'Quiet, were they? You were quieter. That is the lesson.$B$BThese were left in my lantern by someone who did not need them any more.', 0),
(9105031, 1, 'Did they purr? I think they purred. A Devourer that can lie down among its meals and not eat them is a Devourer that will live a long time.$B$BTake this.', 0),
(9105032, 1, 'A cave full of little demons? The Fel Rock? Hagatha says the grell in there used to be sprites, before the fel got them. I''m never sleeping again.$B$BHere, for being brave and for telling me.', 0),
(9105033, 1, 'A long name, and in the end only a meal. Remember that when you meet names longer than hers.$B$BTake your pick. She had no use for them, and neither do I.', 0),
(9105034, 1, 'You patted it! It followed you, didn''t it? Then it went off into the dark on its own, tail up. Moonpaw will remember you, Snack. Cats pretend not to, but they do.$B$BHere''s a cub to keep you company until it comes back. A white one. It won''t replace Moonpaw. Nothing does.', 0),
(9105039, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Darkshore too.', 0),
(9105040, 1, 'Long legs. You will want them one day, when something bigger than you is hungry.$B$BTake one of these.', 0),
(9105041, 1, 'They RAN! I heard them from here! Bullies always run.$B$BHagatha says that was childish. Hagatha also laughed. Here!', 0),
(9105042, 1, 'Sharp, and it stays. That was the crystals'' madness, and the moon''s. Now you know both.$B$BThese came out of the wreck. The draenei will not miss them.', 0),
(9105043, 1, 'It followed you, fell over four times, and then ran off after the flock so fast it caught them. Legs grow into themselves. Stiltz will remember you; striders remember whoever didn''t laugh.$B$BHere''s a chick for you. A Mulgore one. Its legs are the right size.', 0),
(9105049, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Bloodmyst Isle too.', 0),
(9105050, 1, 'Tough, and not much else. Do not underestimate ''not much else'', little horror.$B$BHere.', 0),
(9105051, 1, '*GASP* EIGHT! I held it the WHOLE TIME. I''m a little dizzy. You''re the champion.$B$BHere''s your prize. I''m going to sit down.', 0),
(9105052, 1, 'Patient, wasn''t it, until it wasn''t? That is a crocolisk''s whole secret. Some day the patience will grow teeth, and then more teeth.$B$BTake this, and go west when you are ready.', 0),
(9105053, 1, 'It stopped hissing when you patted it! Then it followed you and fell over its own feet, and then it ran off into the scrub to grow up. Clutchless will remember you. Raptors never forget a face they didn''t bite.$B$BHere''s a hatchling to keep for now. Don''t let it eat Bramble''s boots.', 0),
(9105054, 1, 'Head down, legs going, and six quilboar on their backs. That is the whole boar.$B$BTake this.', 0),
(9105059, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Barrens too.', 0),
(9105060, 1, 'Fast. Stringy. Proud of itself for no reason. A good shape to wear when you need to leave.$B$BTake this.', 0),
(9105061, 1, 'They RAN. One of them ran into a kodo. The kodo was fine.$B$BHagatha says the plains will heal. Here''s something for your trouble.', 0),
(9105062, 1, 'A beast with a name it never wanted. Now it has no name at all, only you.$B$BWear this. And when your plainstrider is ready to grow, remember the taste.', 0),
(9105063, 1, 'He followed you and SNEEZED. Then he howled! A real one, a small one. You did that. Then he went off to find the pack, howling the whole way. Dusty will remember you; wolves always remember the first howl.$B$BHere''s a pup to keep you company until he''s big. It howls already. Dusty will catch up.', 0),
(9105069, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Barrens too.', 0),
(9105070, 1, 'Did you hear them? A heartbeat, a wing, a breath. That is how a bat sees.$B$BTake this.', 0),
(9105071, 1, 'FIVE! Before the candle! What did they taste like? ...Old cheese? I KNEW it.$B$BHere''s your prize. I''m airing out the lantern.', 0),
(9105072, 1, 'Sure of themselves to the very end. Now you are sure of something too.$B$BTake this, and when your bat is ready to grow, remember the taste of red.', 0),
(9105079, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Silverpine Forest too.', 0),
(9105080, 1, 'Sweet and thin, like the elves. That is the taste of magic without anyone holding it.$B$BTake this.', 0),
(9105081, 1, 'The crystal''s empty and so are the stalkers. Well. They''re full. You''re full.$B$BHere, for cleaning up after my science.', 0),
(9105082, 1, 'Hungry things eating hungry things. Do not think about it too long.$B$BTake this, and when your wyrm grows, you will know why I sent you.', 0),
(9105084, 1, 'They did NOT like it. Good. Magic''s not for drinking, it''s for spitting.$B$BHere!', 0),
(9105089, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Ghostlands too.', 0),
(9105100, 1, 'Imaginary stew is DONE. It''s the best stew I''ve never had.$B$BHere''s your bowl. Well. Not a bowl.', 0),
(9105101, 1, 'Thin, and patient, and hungry. You have more in common with them than with the farmers.$B$BTake this.', 0),
(9105103, 1, 'Old, and cold, and finally still. Something in your toad stirred when you swallowed him; I felt it from here.$B$BTake this. You have earned something better than murloc.', 0),
(9105105, 1, 'Peck ORDER. I''ve been waiting all day to say that.$B$BHere!', 0),
(9105109, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Duskwood too.', 0),
(9105110, 1, 'Hard to chew? Good. Something hard to chew is something hard to kill.$B$BTake this.', 0),
(9105111, 1, 'You listened. She listened too; I watched her ears.$B$BNow you know where it comes up. Take this, and when you are ready, go and be worth the climb.', 0),
(9105113, 1, 'A crocolisk that ate a boat, and a Devourer that ate the crocolisk. The children will tell it now.$B$BTake this. And when your komodo is grown enough, it will know what to do.', 0),
(9105114, 1, 'It followed you all the way down! Bears are terrible at climbing down. So am I. I once got stuck in a chimney for a day. Then it lumbered off into the woods to find more honey. Bumble will remember you; bears remember whoever got them down.$B$BHere''s a cub to keep for now, a dwarven one. It won''t climb anything. Probably.', 0),
(9105119, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Wetlands too.', 0),
(9105120, 1, 'Darker. Quieter. Hungrier. Your cat will be all three one day.$B$BTake this.', 0),
(9105121, 1, 'What do they hoot about? The moon, mostly. And you, now. They think you are a late bloomer.$B$BTake this.', 0),
(9105122, 1, 'Moonlight and madness. A heavy meal. Your owl will carry it.$B$BTake this.', 0),
(9105123, 1, 'Did it scream when it died? No. It had nothing left to scream with.$B$BTake this, and when your saber is ready, you will hunt as quietly as that.', 0),
(9105129, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Ashenvale too.', 0),
(9105130, 1, 'Crunchy babies. That sounds bad when I say it out loud.$B$BHere!', 0),
(9105131, 1, 'Some of them are lovely, I said, and I meant it. The flutterers drift over the north of the island, along the Bloodwash. If your moth is ever hungry for a dream that is not yours, you know where they are.$B$BTake this.', 0),
(9105132, 1, 'Home, wasn''t it? Cold and close. Your voidling and your warp stalker will both grow on that taste.$B$BTake this.', 0),
(9105133, 1, 'Dragon! You''ve eaten DRAGON. Well, dragon-ish. I''m telling everyone.$B$BHere''s your prize.', 0),
(9105135, 1, 'Five bears, snoring. I could hear it through the lantern. Did you give them good dreams? I think you did.$B$BHere!', 0),
(9105136, 1, 'The dark saw. It will remember you, and that is no bad thing.$B$BTake this.', 0),
(9105139, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Ashenvale too.', 0),
(9105140, 1, 'Did you feel the wind? That was the chase. One day you will be the one it is chasing.$B$BTake this.', 0),
(9105141, 1, 'They RAN! With their tails down! Who''s laughing now? Us. We''re laughing.$B$BHere, for the best laugh in the Barrens.', 0),
(9105142, 1, 'Your hair is standing up. Do you have hair? Something is standing up.$B$BTake this.', 0),
(9105143, 1, 'Did you feel the sky in it? Good.$B$BTake this. And go and see my sister at her starting line; she has been bursting to tell you something for days.', 0),
(9105144, 1, 'You came! Hagatha thinks her bird can beat you. Her BIRD. Let me tell you about the bet...', 0),
(9105145, 1, 'It followed you, thump thump thump, and then it heard its herd and it RAN. The ground shook. Nobody laughed at it. Little Thunder will remember you; kodos never forget a kindness, it''s why they''re so slow.$B$BHere''s something for the road.', 0),
(9105146, 1, 'Justice! Smelly, shaking justice.$B$BHere''s your reward for being a good agam''ar.', 0),
(9105149, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Stonetalon Mountains too.', 0),
(9105150, 1, 'Clever eyes, and now clever in your belly. Your wolf is listening.$B$BTake this.', 0),
(9105151, 1, 'Silence! Beautiful silence. I''m going to have the best nap.$B$BHere, and goodnight. Don''t wake me.', 0),
(9105152, 1, 'Did they let you? Of course they did. That is what your wolf will be.$B$BTake this.', 0),
(9105153, 1, 'Tidy. I like tidy. The curse will fade; the taste will not.$B$BTake this, little horror. You have earned it.', 0),
(9105155, 1, 'Old blood, but blood. Your duskbat knows what it is for now.$B$BTake this.', 0),
(9105159, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Hillsbrad Foothills too.', 0),
(9105160, 1, 'Honest hunger. Remember the taste; you will meet the other kind soon enough.$B$BTake this.', 0),
(9105162, 1, 'Now there is only one Devourer near the Sanctum of the Moon.$B$BTake this. Your wyrm drank well.', 0),
(9105163, 1, '...three hundred. Are they gone? Really gone? Okay. Okay. I''m coming back to the glass.$B$BHere. You''re very brave. I''m very brave too, for not screaming.', 0),
(9105165, 1, 'Did they taste of anything? Surprise, mostly. That is the taste of a spell that never finished.$B$BTake this.', 0),
(9105169, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Hillsbrad Foothills too.', 0),
(9105170, 1, 'Mad, and hungry, and now part of you. Use it, do not let it use you.$B$BTake this.', 0),
(9105171, 1, 'Now you know why it is dark here. Most people who live here never ask.$B$BTake this, for listening.', 0),
(9105173, 1, 'Did it taste of anything? No. It had forgotten how.$B$BTake this. Your wolf will never forget.', 0),
(9105179, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Stranglethorn Vale too.', 0),
(9105180, 1, 'Patient little things. Now your komodo is patient too.$B$BTake this.', 0),
(9105181, 1, 'Did they curl up around you? Whelps do that, when they are cold. Now you know what it is to have a flight.$B$BTake this.', 0),
(9105182, 1, 'Snort! I''m doing the whelp noise. Snort snort. Bramble believes in them now. She''s a little singed.$B$BHere!', 0),
(9105183, 1, 'Well? Spoons? ...Just old? Then she''s older. HA. I''m telling her.$B$BHere, from me. Not from the spoon.', 0),
(9105189, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Dustwallow Marsh too.', 0),
(9105190, 1, 'Not spirits. Meat. Remember that when the night elves tell you stories.$B$BTake this.', 0),
(9105191, 1, 'Now you know what the satyrs are. When you meet them in the east of the forest, you will taste the difference.$B$BTake this.', 0),
(9105192, 1, 'Bitter, wasn''t it? That is the taste of a shape bought cheap.$B$BTake this.', 0),
(9105193, 1, 'Quiet now, the tower. Your voidcreeper heard every knock.$B$BTake this.', 0),
(9105195, 1, 'Did they scream? They always scream when they meet what they pray to.$B$BTake this.', 0),
(9105199, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Dustwallow Marsh too.', 0),
(9105200, 1, 'Heavy, warm, patient. A good meal for a cold night.$B$BTake this.', 0),
(9105202, 1, 'Honest hunger, again. You will meet it often.$B$BTake this.', 0),
(9105203, 1, 'Warm? Good. Now, when the world bites you, you will bite back from inside your shell, slowly.$B$BTake this.', 0),
(9105209, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Alterac Mountains too.', 0),
(9105210, 1, 'I''m out! Here''s your biscuit. I ate half. Here''s the other half of a prize, too.', 0),
(9105211, 1, 'Three things at once. You are a hundred. Never forget which one you are wearing.$B$BTake this.', 0),
(9105212, 1, 'Bramble says crispy all the way through! I KNEW it. Expert opinion!$B$BHere, a crispy prize.', 0),
(9105213, 1, 'Wild and proud, and now yours. Your whelp has tasted the proto-drake it will become.$B$BTake this.', 0),
(9105215, 1, 'Six kicked! I heard the boots from here. The mountain thanks you, probably.$B$BHere!', 0),
(9105219, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Thousand Needles too.', 0),
(9105220, 1, 'No more nipping! Except me. I nip biscuits.$B$BHere!', 0),
(9105221, 1, 'Did you taste the storm? It is still in you. Your Baby Wind Serpent will feel it.$B$BTake this.', 0),
(9105223, 1, 'Salt and venom and a little crystal. A dry meal, but a long-keeping one.$B$BTake this, and go south when you are ready.', 0),
(9105224, 1, 'You told it a joke? It LAUGHED. A real hyena laugh, with a hiccup in the middle. Then it ran off to show the pack. Giggles will remember you; hyenas remember whoever made them laugh first.$B$BHere''s something for the road. I''d give you a hyena pup, but Hagatha says one laugh in the cauldron room is enough.', 0),
(9105225, 1, 'They never saw you. They never do. That is the viper''s whole gift.$B$BTake this.', 0),
(9105229, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Dustwallow Marsh too.', 0),
(9105230, 1, 'Fast, and foolish, and gone. Your saber is neither now.$B$BTake this.', 0),
(9105232, 1, 'They RAN! From a flex! You''re the strongest-looking thing in Stranglethorn. Hagatha left the room.$B$BHere!', 0),
(9105233, 1, 'The scariest thing in the water! That''s you.$B$BHere. I wanted to give you a frog, but Hagatha says you ARE a frog, sometimes, and that''s enough frog.', 0),
(9105234, 1, 'Dark, and quiet, and yours.$B$BTake this.', 0),
(9105239, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Hinterlands too.', 0),
(9105240, 1, 'Proud, and now humble, inside you.$B$BTake this.', 0),
(9105241, 1, 'Prickly, wasn''t it? That is what being bitten too often tastes like.$B$BTake this.', 0),
(9105243, 1, 'Grin! Big grin! The frogspawn is safe and you are a hero to frogs everywhere.$B$BHere, from all the frogs.', 0),
(9105245, 1, 'You heard. Good. Now go and meet it, and remember: you choose.$B$BTake this.', 0),
(9105246, 1, 'Swollen, and slow, and now inside something that chooses. Your borer will dig.$B$BTake this.', 0),
(9105248, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Tanaris too.', 0),
(9105249, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Feralas too.', 0),
(9105250, 1, 'Big, and now bigger for being in you.$B$BTake this.', 0),
(9105251, 1, 'Free! In a very Hagatha way. Bramble says they looked relieved. I''m going to feel weird about this for a while.$B$BHere.', 0),
(9105252, 1, 'A mountain''s anger, and now yours. Your whelp may grow scales of stone.$B$BTake this.', 0),
(9105253, 1, 'You were. I knew you would be.$B$BThat was a dragon, little horror. A real one. Your drake has eaten its elder; the storm is waiting for it.$B$BTake this.', 0),
(9105254, 1, 'It followed you right past the ogres, head high, and then it bounded off up the mountain where they can''t climb. Nubbin will remember you; goats remember whoever they were brave at.$B$BHere''s something for the road.', 0),
(9105255, 1, 'Stone against stone, and yours was harder.$B$BTake this.', 0),
(9105259, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Hinterlands too.', 0),
(9105260, 1, 'No more sore paws! Well. No more paws. Same thing.$B$BHere!', 0),
(9105261, 1, 'Crunchy. Like a beach. Your teeth will forgive you.$B$BTake this.', 0),
(9105262, 1, 'Prayer and sand. Your serpent is closer to standing up.$B$BTake this.', 0),
(9105264, 1, 'You ate four houses! Bird houses! House birds! I''m too excited.$B$BHere!', 0),
(9105265, 1, 'It stopped stinging its shadow and started following yours. Then it decided your shadow was scarier and scuttled off into the dunes. Prickles will remember you; scorpids remember whoever explained shadows.$B$BHere''s a little scorpion to keep for now. It''s from Durotar. It knows how shadows work.', 0),
(9105266, 1, 'They let you walk through. They will tell their witch doctors, and the witch doctors will not sleep.$B$BTake this.', 0),
(9105269, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Un''Goro Crater too.', 0),
(9105270, 1, 'Long teeth, short lives. Yours are long enough now.$B$BTake this.', 0),
(9105271, 1, 'Iron fur in your tummy! You''re basically armoured now.$B$BHere!', 0),
(9105272, 1, 'Frayed and tired and kind to strangers. Remember that; the sky is not always cruel.$B$BTake this.', 0),
(9105274, 1, 'The forest shook when they fell. It will not shake when you walk now; it will be still.$B$BTake this.', 0),
(9105279, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Winterspring too.', 0),
(9105280, 1, 'Silver in your belly. Shine a little.$B$BTake this.', 0),
(9105281, 1, 'Remember one thing you were. Every night.$B$BTake this.', 0),
(9105282, 1, 'Wild, and moonless. Your moonkin will remember the moon for both of you.$B$BTake this.', 0),
(9105284, 1, 'Old and cross and gone at last. The dwarves will tell it for a hundred years.$B$BTake this.', 0),
(9105289, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Burning Steppes too.', 0),
(9105290, 1, 'Old hunger, in a young world. It suits you.$B$BTake this.', 0),
(9105291, 1, 'No more diving! I can stand up straight again.$B$BHere!', 0),
(9105293, 1, 'Soup, she says. She is not wrong.$B$BTake this.', 0),
(9105294, 1, 'SNAP! You''re the best frog in the crater.$B$BHere, from all the frogs who are scared of wasps.', 0),
(9105296, 1, 'The biggest hunger in the crater, inside the hungriest thing in the world. I am proud of you, little horror. Do not tell Wren I said so.$B$BTake this.', 0),
(9105299, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Terokkar Forest too.', 0),
(9105300, 1, 'Cold, and sharp, and now warm inside you.$B$BTake this.', 0),
(9105302, 1, 'Moonlight and snow. Your saber will remember both, and that the cats of the north let it come home.$B$BTake this.', 0),
(9105303, 1, 'Eight heads! That''s a lot of hats I won''t be knitting.$B$BHere!', 0),
(9105305, 1, 'The moon, in you. Your moonkin will never forget it now.$B$BTake this. You have come a very long way from the first owl.', 0),
(9105309, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Terokkar Forest too.', 0),
(9105310, 1, 'Embers in the belly. Your wolf will not flinch from fire again.$B$BTake this.', 0),
(9105311, 1, 'Ash and fire and dragon. Your drake is learning what it will become.$B$BTake this.', 0),
(9105313, 1, 'Elders, eaten. Your drake has nothing left to look up to but the storm.$B$BTake this.', 0),
(9105314, 1, 'Do you feel it, behind your ribs? Thunder. The storm is gathering in you.$B$BTake this.', 0),
(9105319, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Terokkar Forest too.', 0),
(9105320, 1, 'Bigger worlds, bigger wolves, bigger you.$B$BTake this.', 0),
(9105322, 1, 'Dark and cold and familiar. Your warp stalker is ready to forget which side it belongs to.$B$BTake this.', 0),
(9105323, 1, 'A Devourer, not a thief. Good.$B$BTake this.', 0),
(9105324, 1, 'Bone appetit! I''ve been saving that one.$B$BHere!', 0),
(9105329, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Nagrand too.', 0),
(9105330, 1, 'Sweet, wasn''t it? Remember it.$B$BTake this.', 0),
(9105331, 1, 'Big dreams, big bird, big Snack!$B$BHere!', 0),
(9105333, 1, 'Nothing, eaten. It tastes like home, doesn''t it?$B$BTake this.', 0),
(9105339, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Netherstorm too.', 0),
(9105340, 1, 'Forgotten. Good.$B$BTake this.', 0),
(9105341, 1, 'Slippery. Now so are you.$B$BTake this.', 0),
(9105343, 1, 'Shimmer shimmer! And nobody even noticed you. You''re a natural.$B$BHere!', 0),
(9105344, 1, 'A colour from beyond the world. Your drake will be strange now. Good.$B$BTake this, and go home, and then go north.', 0),
(9105345, 1, 'The storm saw. It will think twice before it throws anything else loose.$B$BTake this.', 0),
(9105348, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Howling Fjord too.', 0),
(9105349, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Borean Tundra too.', 0),
(9105350, 1, 'Warm now? Good.$B$BTake this.', 0),
(9105351, 1, 'Stay wild. Now go and meet the ones who did.$B$BTake this.', 0),
(9105352, 1, 'Wild and hungry and proud, and they took you in. You fit right in, as I said.$B$BTake this.', 0),
(9105353, 1, 'Your drake has met itself and eaten it. That is the most a Devourer can do.$B$BTake this.', 0),
(9105359, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Grizzly Hills too.', 0),
(9105360, 1, 'Wool and horn. Warm and hard. Both useful here.$B$BTake this.', 0),
(9105361, 1, 'Bless you! Bless your moth!$B$BHere!', 0),
(9105363, 1, 'Arrogance, eaten. It tastes like everything else, in the end.$B$BTake this.', 0),
(9105369, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in Sholazar Basin too.', 0),
(9105370, 1, 'Can you hear it? Your wolf is singing.$B$BTake this.', 0),
(9105371, 1, 'The sky is yours! Shh.$B$BHere!', 0),
(9105372, 1, 'Quickly. Without anger. Remember him.$B$BTake this.', 0),
(9105374, 1, 'Remembered. Ursoc will not mind; bears understand hunger.$B$BTake this.', 0),
(9105379, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Storm Peaks too.', 0),
(9105381, 1, 'Logs eaten! Your komodo says thank you.$B$BHere!', 0),
(9105382, 1, 'Hunter of hunters. That is what you are.$B$BTake this.', 0),
(9105383, 1, 'FOUR! Spoon Hardknuckle is official! It''s the best spoon in Northrend.$B$BHere!', 0),
(9105385, 1, 'The first dragons, nearly. Your drake has eaten its whole history now.$B$BTake this, and go to the peaks.', 0),
(9105389, 1, 'You found it. Of course you did; you follow your stomach, and your stomach follows me.$B$BSit. Listen. There is hunger in the Storm Peaks too.', 0),
(9105390, 1, 'Crunch! Like ice! I knew it.$B$BHere!', 0),
(9105391, 1, 'As big as ships, and gone. Your borer will dig to the heart of the world.$B$BTake this.', 0),
(9105392, 1, 'It followed you right out of sight of the vrykul and then curled up in a snowdrift and went to sleep. No war for that one. Snowdrift will remember you; bears remember whoever let them sleep.$B$BHere''s a polar cub to keep for now. It''s never been to war either. It''s only been to Winter Veil.', 0),
(9105393, 1, 'Do you hear it? That is the storm, and it is in you.$B$BTake this. You are nearly at the end of my lanterns, little horror. Come back to the fire when you are ready.', 0),
(9105394, 1, 'They saw. The whole sky saw.$B$BI have nothing left to teach you. Take this, and come and sit with us in the In-Between some evening. Wren will make soup. Do not eat Wren.', 0),
(9105395, 1, 'That is all, little horror. That is the whole tale, so far.$B$B[Wren] SO FAR. There''ll be more. Here, this is from both of us.', 0);
INSERT INTO `creature_queststarter` (`id`, `quest`) VALUES (9101300, 9105001), (9101300, 9105002), (9101300, 9105003), (9101300, 9105004), (9101300, 9105005), (9101300, 9105006), (9101300, 9105007), (9101300, 9105008);
